<?php $thumbnail = $video['thumbnail'] ? store_image($video['thumbnail']) : 'https://i.ytimg.com/vi/' . rawurlencode($video['youtube_id']) . '/hqdefault.jpg'; ?>
<article class="video-card h-100"><a class="video-card-media" href="<?= url_to('videos.show', $video['slug']) ?>"><img src="<?= esc($thumbnail, 'attr') ?>" width="640" height="360" loading="lazy" decoding="async" alt="<?= esc($video['title'], 'attr') ?>"><span class="video-play" aria-hidden="true">▶</span><?php if ($video['duration']): ?><span class="video-duration"><?= esc($video['duration']) ?></span><?php endif ?></a><div class="video-card-body"><?php if (!empty($video['category_name'])): ?><span class="video-eyebrow"><?= esc($video['category_name']) ?></span><?php endif ?><h3><a href="<?= url_to('videos.show', $video['slug']) ?>"><?= esc($video['title']) ?></a></h3><?php if ($video['short_description']): ?><p><?= esc($video['short_description']) ?></p><?php endif ?></div></article>
